require __DIR__.'/../includes/bootstrap.php';$pdo=database();if(empty($_SESSION['account']['id'])){header('Location: /account.php#login');exit;}$uid=(int)$_SESSION['account']['id'];$check=$pdo->prepare("SELECT 1 FROM user_pillar_roles upr JOIN roles r ON r.id=upr.role_id WHERE upr.user_id=:uid AND upr.status='active' AND r.code='farm_owner'");$check->execute(['uid'=>$uid]);$allowed=(bool)$check->fetchColumn();if(!$allowed){$check=$pdo->prepare("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=:uid AND r.code='admin'");$check->execute(['uid'=>$uid]);$allowed=(bool)$check->fetchColumn();}if(!$allowed){http_response_code(403);$pageTitle='Farm owner access required';require __DIR__.'/../includes/header.php';echo '<main class="site-page section-pad"><div class="container"><h1>Farm Owner access required</h1><a class="btn btn-darkgreen" href="/account.php?view=roles">Apply for role</a></div></main>';require __DIR__.'/../includes/footer.php';exit;}
$_SESSION['farm_csrf']??=bin2hex(random_bytes(32));$notice='';if($_SERVER['REQUEST_METHOD']==='POST'){try{if(!hash_equals($_SESSION['farm_csrf'],(string)($_POST['_token']??'')))throw new RuntimeException('Session expired. Please try again.');$id=(int)($_POST['farm_id']??0);$name=trim((string)($_POST['farm_name']??''));$location=trim((string)($_POST['farm_location']??''));if($name===''||$location==='')throw new RuntimeException('Enter the farm name and full farm location.');if($id>0){$q=$pdo->prepare('UPDATE providers SET name=:name,location=:loc,status=\'approved\' WHERE id=:id AND owner_user_id=:uid');$q->execute(['name'=>$name,'loc'=>$location,'id'=>$id,'uid'=>$uid]);if(!$q->rowCount())throw new RuntimeException('Farm profile was not found.');$q=$pdo->prepare("UPDATE listings SET location=:loc,provider_name=:name WHERE provider_id=:id AND pillar='Agri-Fishery' AND item_type='Product'");$q->execute(['loc'=>$location,'name'=>$name,'id'=>$id]);$_SESSION['flash']='Farm profile and its product locations were updated.';}else{$q=$pdo->prepare("INSERT INTO providers(owner_user_id,name,location,status) VALUES(:uid,:name,:loc,'approved') RETURNING id");$q->execute(['uid'=>$uid,'name'=>$name,'loc'=>$location]);$_SESSION['flash']='Farm location added to your seller account.';}header('Location: /account.php?role=farm_owner&view=farm');exit;}catch(Throwable $e){$notice=$e instanceof PDOException&&$e->getCode()==='23505'?'A farm with that name already exists.':$e->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT id,name,location FROM providers WHERE id=:id AND owner_user_id=:uid');$q->execute(['id'=>(int)$_GET['edit'],'uid'=>$uid]);$edit=$q->fetch()?:null;}if(!$edit&&!isset($_GET['edit'])){$edit=['id'=>0,'name'=>'','location'=>''];}
$pageTitle='Farm profile — Agri-Fishery — Kabulig Portal';$currentPillar='Agri-Fishery';require __DIR__.'/../includes/header.php';?>
<main class="site-page"><section class="site-page-hero account-compact-hero"><div class="container"><div class="eyebrow">FARM OWNER DASHBOARD</div><h1><?= !empty($edit['id'])?'Edit your':'Add a' ?> <em>farm profile.</em></h1><p>Every product is attached to one of your farm profiles and uses its registered location.</p></div></section><section class="section-pad"><div class="container"><section class="account-content-panel seller-product-form"><a class="back-link" href="/account.php?role=farm_owner&view=farm"><i class="fa-solid fa-arrow-left"></i> Back to Farm Dashboard</a><h2><?= !empty($edit['id'])?'Update farm details':'Farm details' ?></h2><?php if($notice!==''): ?><div class="admin-notice"><?= h($notice) ?></div><?php endif; ?><form method="post"><input type="hidden" name="_token" value="<?= h($_SESSION['farm_csrf']) ?>"><input type="hidden" name="farm_id" value="<?= (int)($edit['id']??0) ?>"><div class="seller-product-fields"><label>Farm name<input name="farm_name" value="<?= h($edit['name']??'') ?>" required></label><label>Farm location<input name="farm_location" value="<?= h($edit['location']??'') ?>" placeholder="Barangay, municipality, province" required></label></div><p class="farm-location-note"><i class="fa-solid fa-link"></i> Products linked to this farm will use this location automatically.</p><button class="btn btn-darkgreen" type="submit"><?= !empty($edit['id'])?'Save farm profile':'Add farm to my account' ?></button></form></section></div></section></main><?php require __DIR__.'/../includes/footer.php'; ?>
